// User-specific data changes on every request, so opt out of caching
async function getUserPreferences() {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) throw new Error(`Failed to fetch preferences: ${res.status}`)
    return res.json()
  } catch {
    // Return mock data when the API is unavailable (e.g. at build time)
    return { theme: 'light', language: 'en', notifications: true }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        {Object.entries(preferences).map(([key, value]) => (
          <li key={key}>
            {key}: {String(value)}
          </li>
        ))}
      </ul>
    </div>
  )
}

